import{J as e,n as t,ot as n,q as r}from"./chunks/framework.BCRZU8Rs.js";var i=JSON.parse(`{"title":"Class: ChunkHolderMap<TChunk>","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: ChunkHolderMap<TChunk>"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/ChunkHolderMap"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/ChunkHolderMap"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/chunkgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/chunkgen/classes/ChunkHolderMap.md","filePath":"api/@jsprismarine/chunkgen/classes/ChunkHolderMap.md","lastUpdated":1794433523000}`),a={name:`api/@jsprismarine/chunkgen/classes/ChunkHolderMap.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/chunkgen</a> / ChunkHolderMap</p><h1 id="class-chunkholdermap-tchunk" tabindex="-1">Class: ChunkHolderMap&lt;TChunk&gt; <a class="header-anchor" href="#class-chunkholdermap-tchunk" aria-label="Permalink to “Class: ChunkHolderMap&lt;TChunk&gt;”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L18" target="_blank" rel="noreferrer">ChunkHolderMap.ts:18</a></p><p>The holders a generation run is working on, kept alive by reference count.</p><p>This replaces the generator&#39;s 128-entry LRU of neighbor terrain. An LRU is the wrong retention rule here for a reason that is measurable rather than stylistic: <code>preload-radius: 5</code> is 121 chunks, which sits right at the edge of 128, so a feature pass&#39;s write into a neighbor could land on a holder that had already been evicted and silently do nothing. A count answers the question that actually matters, which is whether anything still needs the chunk.</p><p>Java spends a ticket level on the same job. The shape here is the narrow part of that: a generation task acquires every holder inside its radius before it runs a single step, and releases them all when it finishes, so nothing it depends on can be dropped while it is in flight. A caller that wants a chunk to stay resident past a run acquires its own reference.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="tchunk" tabindex="-1">TChunk <a class="header-anchor" href="#tchunk" aria-label="Permalink to “TChunk”">​</a></h3><p><code>TChunk</code> <em>extends</em> <a href="./../#stagedchunk"><code>StagedChunk</code></a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ChunkHolderMap</strong>&lt;<code>TChunk</code>&gt;(<code>newChunk</code>): <code>ChunkHolderMap</code>&lt;<code>TChunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L26" target="_blank" rel="noreferrer">ChunkHolderMap.ts:26</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="newchunk" tabindex="-1">newChunk <a class="header-anchor" href="#newchunk" aria-label="Permalink to “newChunk”">​</a></h5><p>(<code>chunkX</code>, <code>chunkZ</code>) =&gt; <code>TChunk</code></p><p>Allocates the chunk a new holder starts from, called once per holder on its first step. The server passes the dimension&#39;s build height through here, and a test passes a short column.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ChunkHolderMap</code>&lt;<code>TChunk</code>&gt;</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="size" tabindex="-1">size <a class="header-anchor" href="#size" aria-label="Permalink to “size”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>size</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L29" target="_blank" rel="noreferrer">ChunkHolderMap.ts:29</a></p><p>How many holders are retained. Zero after every task has released what it took.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="acquire" tabindex="-1">acquire() <a class="header-anchor" href="#acquire" aria-label="Permalink to “acquire()”">​</a></h3><blockquote><p><strong>acquire</strong>(<code>chunkX</code>, <code>chunkZ</code>): <a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L48" target="_blank" rel="noreferrer">ChunkHolderMap.ts:48</a></p><p>Takes a reference on a chunk&#39;s holder, creating the holder when this is the first one.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><h5 id="chunkz" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt;</p><p>The holder, which the caller must release exactly once.</p><hr><h3 id="acquiresquare" tabindex="-1">acquireSquare() <a class="header-anchor" href="#acquiresquare" aria-label="Permalink to “acquireSquare()”">​</a></h3><blockquote><p><strong>acquireSquare</strong>(<code>centerX</code>, <code>centerZ</code>, <code>radius</code>): readonly <a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt;[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L86" target="_blank" rel="noreferrer">ChunkHolderMap.ts:86</a></p><p>Takes a reference on every chunk in the square of <code>radius</code> chunks around a center.</p><p>Java&#39;s <code>ChunkGenerationTask.create</code> fills a <code>StaticCache2D</code> the same way and for the same reason: a task that acquired its neighborhood lazily could find a holder it is about to read dropped by whichever task released last.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="centerx" tabindex="-1">centerX <a class="header-anchor" href="#centerx" aria-label="Permalink to “centerX”">​</a></h5><p><code>number</code></p><h5 id="centerz" tabindex="-1">centerZ <a class="header-anchor" href="#centerz" aria-label="Permalink to “centerZ”">​</a></h5><p><code>number</code></p><h5 id="radius" tabindex="-1">radius <a class="header-anchor" href="#radius" aria-label="Permalink to “radius”">​</a></h5><p><code>number</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt;[]</p><p>The holders, row major with x ascending fastest, each owing one release.</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>chunkX</code>, <code>chunkZ</code>): <a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt; | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L34" target="_blank" rel="noreferrer">ChunkHolderMap.ts:34</a></p><p>The holder for a chunk, or undefined when nothing retains it.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx-1" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx-1" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><h5 id="chunkz-1" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz-1" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt; | <code>undefined</code></p><hr><h3 id="release" tabindex="-1">release() <a class="header-anchor" href="#release" aria-label="Permalink to “release()”">​</a></h3><blockquote><p><strong>release</strong>(<code>chunkX</code>, <code>chunkZ</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L65" target="_blank" rel="noreferrer">ChunkHolderMap.ts:65</a></p><p>Gives back a reference, dropping the holder when it was the last one.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx-2" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx-2" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><h5 id="chunkz-2" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz-2" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether the holder was dropped.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>RangeError when nothing holds a reference on that chunk, which means a task released twice and the next release would drop a holder another task is reading.</p><hr><h3 id="releaseall" tabindex="-1">releaseAll() <a class="header-anchor" href="#releaseall" aria-label="Permalink to “releaseAll()”">​</a></h3><blockquote><p><strong>releaseAll</strong>(<code>holders</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L95" target="_blank" rel="noreferrer">ChunkHolderMap.ts:95</a></p><p>Gives back one reference on each of the holders, dropping those that reach zero.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="holders" tabindex="-1">holders <a class="header-anchor" href="#holders" aria-label="Permalink to “holders”">​</a></h5><p><code>Iterable</code>&lt;<a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt;&gt;</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="values" tabindex="-1">values() <a class="header-anchor" href="#values" aria-label="Permalink to “values()”">​</a></h3><blockquote><p><strong>values</strong>(): <code>IterableIterator</code>&lt;<a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bd902c1bcd11462b3439bdfb487a5a2242bbe49b/packages/chunkgen/src/ChunkHolderMap.ts#L39" target="_blank" rel="noreferrer">ChunkHolderMap.ts:39</a></p><p>Every retained holder, in the order the holders were created.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>IterableIterator</code>&lt;<a href="./ChunkHolder.html"><code>ChunkHolder</code></a>&lt;<code>TChunk</code>&gt;&gt;</p>`,100)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};